DECLARE
  TYPE
    Concentration = 1.0 : 0.0 : 100.0 UNIT = "mol/L"
    Temperature   = 350.0 : 250.0 : 600.0 UNIT = "K"
    FlowRate      = 1.0 : 0.0 : 100.0 UNIT = "L/s"
    ReactionRate  = 0.0 : -1000.0 : 1000.0 UNIT = "mol/(L*s)"
  END
END

MODEL JacketedCSTR
  PARAMETER
    V     AS REAL DEFAULT 100.0
    k0    AS REAL DEFAULT 7.2e6
    E_R   AS REAL DEFAULT 5500.0
    dH_rx AS REAL DEFAULT -50000.0
    rhoCp AS REAL DEFAULT 4184.0
    UA    AS REAL DEFAULT 5000.0

  VARIABLE
    C_A    AS Concentration
    T      AS Temperature
    F      AS FlowRate
    C_A_in AS Concentration
    T_in   AS Temperature
    T_cool AS Temperature
    r      AS ReactionRate

  EQUATION
    r = k0 * EXP(-E_R / T) * C_A ;
    $C_A = (F / V) * (C_A_in - C_A) - r ;
    $T = (F / V) * (T_in - T) + (-dH_rx / rhoCp) * r - (UA / (V * rhoCp)) * (T - T_cool) ;
END

PROCESS JacketedCstrRun
  UNIT
    R201 AS JacketedCSTR
  SET
    R201.V := 100.0 ;
    R201.k0 := 7.2e6 ;
    R201.E_R := 5500.0 ;
    R201.dH_rx := -50000.0 ;
    R201.rhoCp := 4184.0 ;
    R201.UA := 5000.0 ;
  ASSIGN
    R201.F := 1.5 ;
    R201.C_A_in := 2.0 ;
    R201.T_in := 330.0 ;
    R201.T_cool := 300.0 ;
  INITIAL
    R201.C_A := 1.0 ;
    R201.T := 340.0 ;
  SOLUTIONPARAMETERS
    ReportingInterval := 0.5 ;
    TotalTime := 60.0 ;
END

DECLARE
  TYPE
    MoleFraction = 0.5 : 0.0 : 1.0 UNIT = "mol/mol"
    MolarFlow    = 10.0 : 0.0 : 500.0 UNIT = "mol/s"
  END
END

MODEL BinaryDistillationColumn
  PARAMETER
    alpha AS REAL DEFAULT 2.4
    M_reb AS REAL DEFAULT 50.0
    M_tr  AS REAL DEFAULT 20.0
    M_con AS REAL DEFAULT 30.0

  VARIABLE
    x_reb AS MoleFraction
    x_tr  AS MoleFraction
    x_con AS MoleFraction
    y_reb AS MoleFraction
    y_tr  AS MoleFraction
    F_in  AS MolarFlow
    z_in  AS MoleFraction
    L_ref AS MolarFlow
    V_boil AS MolarFlow

  EQUATION
    y_reb = (alpha * x_reb) / (1.0 + (alpha - 1.0) * x_reb) ;
    y_tr  = (alpha * x_tr) / (1.0 + (alpha - 1.0) * x_tr) ;
    M_reb * $x_reb = (L_ref + F_in) * x_tr - V_boil * y_reb - (L_ref + F_in - V_boil) * x_reb ;
    M_tr  * $x_tr  = F_in * z_in + L_ref * x_con + V_boil * y_reb - (L_ref + F_in) * x_tr - V_boil * y_tr ;
    M_con * $x_con = V_boil * y_tr - L_ref * x_con - (V_boil - L_ref) * x_con ;
END

PROCESS DistillationStartup
  UNIT
    C401 AS BinaryDistillationColumn
  SET
    C401.alpha := 2.4 ;
    C401.M_reb := 50.0 ;
    C401.M_tr  := 20.0 ;
    C401.M_con := 30.0 ;
  ASSIGN
    C401.F_in   := 10.0 ;
    C401.z_in   := 0.50 ;
    C401.L_ref  := 15.0 ;
    C401.V_boil := 20.0 ;
  INITIAL
    C401.x_reb := 0.50 ;
    C401.x_tr  := 0.50 ;
    C401.x_con := 0.50 ;
  SOLUTIONPARAMETERS
    ReportingInterval := 0.5 ;
    TotalTime := 40.0 ;
END

DECLARE
  TYPE
    Concentration = 1.0 : 0.0 : 100.0 UNIT = "mol/L"
    FlowRate      = 2.0 : 0.0 : 1000.0 UNIT = "L/s"
    ReactionRate  = 0.0 : -1000.0 : 1000.0 UNIT = "mol/(L*s)"
  END
END

MODEL ReactorSeparatorPlant
  PARAMETER
    V_rx  AS REAL DEFAULT 25.0
    V_sep AS REAL DEFAULT 15.0
    k_rx  AS REAL DEFAULT 0.35
    eta_s AS REAL DEFAULT 0.85

  VARIABLE
    C_A_rx  AS Concentration
    C_B_rx  AS Concentration
    C_A_sep AS Concentration
    C_B_sep AS Concentration
    F_fresh AS FlowRate
    F_rec   AS FlowRate
    C_A0    AS Concentration
    r_rx    AS ReactionRate

  EQUATION
    r_rx = k_rx * C_A_rx ;
    V_rx * $C_A_rx = F_fresh * C_A0 + F_rec * C_A_sep - (F_fresh + F_rec) * C_A_rx - V_rx * r_rx ;
    V_rx * $C_B_rx = F_rec * (1.0 - eta_s) * C_B_sep - (F_fresh + F_rec) * C_B_rx + V_rx * r_rx ;
    V_sep * $C_A_sep = (F_fresh + F_rec) * (C_A_rx - C_A_sep) ;
    V_sep * $C_B_sep = (F_fresh + F_rec) * (C_B_rx - C_B_sep) ;
END

PROCESS PlantwideRecycleRun
  UNIT
    P501 AS ReactorSeparatorPlant
  SET
    P501.V_rx  := 25.0 ;
    P501.V_sep := 15.0 ;
    P501.k_rx  := 0.35 ;
    P501.eta_s := 0.85 ;
  ASSIGN
    P501.F_fresh := 2.0 ;
    P501.F_rec   := 1.5 ;
    P501.C_A0    := 10.0 ;
  INITIAL
    P501.C_A_rx  := 2.0 ;
    P501.C_B_rx  := 0.0 ;
    P501.C_A_sep := 2.0 ;
    P501.C_B_sep := 0.0 ;
  SOLUTIONPARAMETERS
    ReportingInterval := 0.2 ;
    TotalTime := 30.0 ;
END

